import React, { useContext } from 'react';
import { Link } from 'react-router-dom';
import { AuthContext } from '../context/AuthContext';

const Navbar = () => {
  const { isAuthenticated, user, logout } = useContext(AuthContext);

  return (
    <nav className="flex justify-between items-center px-8 py-5 bg-[#0A0E1A]/95 backdrop-blur-md border-b border-slate-800/60 sticky top-0 z-50">
      {/* LOGO — icône + wordmark */}
      <Link to="/" className="flex items-center gap-2.5 group">
        <div className="w-9 h-9 rounded-lg bg-gradient-to-br from-blue-500 to-cyan-400 flex items-center justify-center font-black text-[#0A0E1A] text-lg shadow-lg shadow-blue-500/20 group-hover:scale-105 transition-transform">
          A
        </div>
        <span className="text-lg font-extrabold tracking-tight text-white">
          AVALON <span className="text-blue-400 font-medium">SECURE</span>
        </span>
      </Link>

      <div className="flex gap-3 items-center">
        {!isAuthenticated ? (
          <Link
            to="/login"
            className="bg-blue-600 hover:bg-blue-500 text-white text-sm font-semibold px-5 py-2.5 rounded-lg transition-colors shadow-md shadow-blue-600/20"
          >
            Connexion
          </Link>
        ) : (
          <>
            {user?.role === 'admin' && (
              <Link
                to="/admin"
                className="text-sm font-semibold text-blue-400 hover:text-blue-300 px-4 py-2 rounded-lg hover:bg-blue-500/10 transition-colors"
              >
                Console Admin
              </Link>
            )}
            <Link
              to="/dashboard"
              className="text-sm font-semibold text-slate-300 hover:text-white px-4 py-2 rounded-lg hover:bg-slate-800/60 transition-colors"
            >
              Mon Apprentissage
            </Link>
            <button
              onClick={logout}
              className="text-sm font-semibold text-red-400 hover:text-red-300 px-4 py-2 rounded-lg hover:bg-red-500/10 transition-colors"
            >
              Déconnexion
            </button>
            <div className="w-9 h-9 rounded-full bg-gradient-to-br from-slate-700 to-slate-800 border border-slate-600 flex items-center justify-center text-xs font-bold text-white">
              {user?.email?.[0]?.toUpperCase() || 'U'}
            </div>
          </>
        )}
      </div>
    </nav>
  );
};
export default Navbar;
